#[derive(Clone, Debug, Default, PartialEq)]
pub struct F2SeatAction {
    pub kind: F2SeatActionKind,
    pub unit: Option<Ref<Unit>>,
    pub holder: f64,
    pub turret: bool,
    pub index: f64,
    pub lease: Option<Ref<SeatLease>>,
    pub post: Option<Ref<Post>>,
    pub reason: SeatReason,
    pub effect: SeatEffectKind,
    pub point: Vec3,
    pub direction: Vec3,
    pub yaw: f64,
    pub flag: bool,
    pub second: bool,
    pub attacker: Attacker,
}

impl F2SeatAction {
    pub const WORDS: usize = 27;

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 27] = (&mut row[..27]).try_into().unwrap();
        row[0] = self.kind as u8 as f64;
        match &self.unit { Some(v) => { row[1] = 0.0; row[1 + 1] = (*v).slot as f64; row[1 + 1 + 1] = (*v).gen as f64; } None => { row[1] = 1.0; row[1 + 1..1 + 3].fill(0.0); } }
        row[4] = self.holder;
        row[5] = if self.turret { 1.0 } else { 0.0 };
        row[6] = self.index;
        match &self.lease { Some(v) => { row[7] = 0.0; row[7 + 1] = (*v).slot as f64; row[7 + 1 + 1] = (*v).gen as f64; } None => { row[7] = 1.0; row[7 + 1..7 + 3].fill(0.0); } }
        match &self.post { Some(v) => { row[10] = 0.0; row[10 + 1] = (*v).slot as f64; row[10 + 1 + 1] = (*v).gen as f64; } None => { row[10] = 1.0; row[10 + 1..10 + 3].fill(0.0); } }
        row[13] = self.reason as u8 as f64;
        row[14] = self.effect as u8 as f64;
        row[15..15 + 3].copy_from_slice(&self.point);
        row[18..18 + 3].copy_from_slice(&self.direction);
        row[21] = self.yaw;
        row[22] = if self.flag { 1.0 } else { 0.0 };
        row[23] = if self.second { 1.0 } else { 0.0 };
        self.attacker.put(&mut row[24..24 + 3], heap);
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 27] = (&row[..27]).try_into().unwrap();
        Self {
            kind: F2SeatActionKind::from_u8(word_u32(row[0]) as u8).unwrap_or_default(),
            unit: if row[1] == 0.0 { Some(Ref::new(word_u32(row[1 + 1]), word_u32(row[1 + 1 + 1]))) } else { None },
            holder: row[4],
            turret: row[5] != 0.0,
            index: row[6],
            lease: if row[7] == 0.0 { Some(Ref::new(word_u32(row[7 + 1]), word_u32(row[7 + 1 + 1]))) } else { None },
            post: if row[10] == 0.0 { Some(Ref::new(word_u32(row[10 + 1]), word_u32(row[10 + 1 + 1]))) } else { None },
            reason: SeatReason::from_u8(word_u32(row[13]) as u8).unwrap_or_default(),
            effect: SeatEffectKind::from_u8(word_u32(row[14]) as u8).unwrap_or_default(),
            point: [row[15], row[15 + 1], row[15 + 2]],
            direction: [row[18], row[18 + 1], row[18 + 2]],
            yaw: row[21],
            flag: row[22] != 0.0,
            second: row[23] != 0.0,
            attacker: Attacker::take(&row[24..24 + 3], heap),
        }
    }

}

